{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C38"],
      "claim": "Abemaciclib, a heteroaromatic oral drug with a basic piperazine side chain, has an absolute oral bioavailability of 0.448 in healthy subjects; this direct human F measurement strongly supports high bioavailability for the similarly heteroaromatic/basic query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C34"],
      "claim": "Doxazosin, containing a quinazoline and piperazine amide, has an absolute oral bioavailability of 69% in elderly patients; this high human F supports the query's benzimidazole/morpholine scaffold being well absorbed.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C35"],
      "claim": "Mizolastine, a benzimidazole-like antihistamine with basic amine and heteroaromatic rings, has an absolute oral bioavailability of 70% in healthy volunteers, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Gefitinib, an oral kinase inhibitor with a morpholinopropoxy side chain, has ~60% oral bioavailability in humans, directly supporting high F for the query's morpholine-containing heteroaromatic structure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Abecarnil, despite variable absorption, has an absolute oral bioavailability of 39±17% in healthy volunteers, still well above the 20% threshold and supportive of high F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All retrieved analogues with high assay-transfer scores show oral bioavailability values well above 20% (mostly 39-71%), including multiple absolute human F determinations. The query's heteroaromatic/azole and morpholine features are represented among these high-F drugs, so high bioavailability is strongly supported.",
  "evidence_gaps": [
    "No direct experimental bioavailability measurement for the query molecule.",
    "No human PK data for the exact query structure.",
    "Solubility, permeability, and first-pass metabolism of the query were not directly assessed."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

